      -webkit-backdrop-filter: blur(60px) contrast(.85) saturate(1.3);
      border: 1px solid rgba(255,255,255,.1);
    }.sc-tw .bloom{
      opacity: 0;
      transform: translateY(60px) scale(.96);
      transition:
        opacity 1.2s cubic-bezier(.16,1,.3,1),
        transform 1.2s cubic-bezier(.16,1,.3,1);
    }.sc-tw .bloom.active{
      opacity: 1;
      transform: translateY(0) scale(1);
    }.sc-tw .pulse-react{
      animation: pulseReact 4s ease-in-out infinite;
    }.sc-tw .light-river{
      position: absolute;
      inset: auto 0;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(97,218,251,.35), rgba(140,255,180,.4), transparent);
      filter: blur(.4px);
